using System;
using System.Diagnostics;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
namespace Ember;
public sealed class EffectEditor : Window
{
 private readonly CustomEffect effect;
 private readonly TextBox name=new(){Height=40},duration=new(){Height=38};private readonly ColorPicker palette=new();
 private readonly CheckBox repeat=new(){Content="Повторювати по колу"};
 private readonly ComboBox trigger=new(),transition=new();
 private readonly TextBox threshold=new(){Height=38},beatCount=new(){Height=38},hold=new(){Height=38},timeout=new(){Height=38};
 private static readonly StepTrigger[] triggers={StepTrigger.Timer,StepTrigger.MusicBeat,StepTrigger.MusicBass,StepTrigger.MusicPeak,StepTrigger.MusicSilence,StepTrigger.MusicLevel,StepTrigger.Manual,StepTrigger.MusicBeatOrTimer};private readonly StackPanel rows=new();
 private readonly TextBlock info=new(){Foreground=new SolidColorBrush(Color.FromRgb(255,90,31)),FontSize=11};
 private readonly Button record=new(){Content="● Записати наживо"};
 private readonly Stopwatch watch=Stopwatch.StartNew();private readonly LiveEffectRecorder live=new();private bool recording=>live.Active;private int selected;private bool updating;
 public CustomEffect? Result{get;private set;}
 private Brush Accent=>(Brush)FindResource("Ember");
 public EffectEditor(CustomEffect? existing=null)
 {
  WindowFit.Attach(this);effect=existing?.Clone()??new CustomEffect{Steps={new EffectStep()}};Title="Ember · Студія ефектів";Width=1030;Height=740;MinWidth=900;MinHeight=650;Background=new SolidColorBrush(Color.FromRgb(7,7,7));Foreground=Brushes.White;WindowStyle=WindowStyle.None;WindowStartupLocation=WindowStartupLocation.CenterOwner;FontFamily=new("Inter, Segoe UI");
  var shell=new Border{BorderBrush=new SolidColorBrush(Color.FromArgb(40,255,255,255)),BorderThickness=new(1),CornerRadius=new(16),Padding=new(24)};Content=shell;
  var grid=new Grid();grid.RowDefinitions.Add(new(){Height=GridLength.Auto});grid.RowDefinitions.Add(new(){Height=new(1,GridUnitType.Star)});grid.RowDefinitions.Add(new(){Height=GridLength.Auto});shell.Child=grid;
  var head=new Grid{Margin=new(0,0,0,22)};head.ColumnDefinitions.Add(new(){Width=new(1,GridUnitType.Star)});head.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var heading=new StackPanel();heading.Children.Add(new TextBlock{Text="СТУДІЯ ЕФЕКТІВ",FontSize=10,Foreground=Accent});heading.Children.Add(new TextBlock{Text="Твій світловий сценарій.",FontSize=25,FontWeight=FontWeights.SemiBold,Margin=new(0,6,0,0)});head.Children.Add(heading);head.MouseLeftButtonDown+=(_,e)=>{if(e.LeftButton==MouseButtonState.Pressed)DragMove();};var close=new Button{Content="×",Padding=new(12,6,12,6),VerticalAlignment=VerticalAlignment.Top};close.Click+=(_,_)=>Close();Grid.SetColumn(close,1);head.Children.Add(close);grid.Children.Add(head);
  var body=new Grid();Grid.SetRow(body,1);body.ColumnDefinitions.Add(new(){Width=new(285)});body.ColumnDefinitions.Add(new(){Width=new(20)});body.ColumnDefinitions.Add(new(){Width=new(1,GridUnitType.Star)});grid.Children.Add(body);
  palette.WheelSize=160;var left=new StackPanel();var card=new Border{Style=(Style)FindResource("Card"),Padding=new(18),Child=new ScrollViewer{Content=left,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled}};body.Children.Add(card);
  Label(left,"КОЛІР КРОКУ");left.Children.Add(palette);Label(left,"ТРИВАЛІСТЬ, СЕКУНДИ",12);left.Children.Add(duration);Label(left,"ПЕРЕХІД ДО ЦЬОГО КОЛЬОРУ",12);transition.Items.Add("Миттєво");transition.Items.Add("Плавно за час кроку");left.Children.Add(transition);Label(left,"ПЕРЕЙТИ ДАЛІ ПІСЛЯ",12);foreach(var label in new[]{"Таймер","Нові біти музики","Бас вище порога","Пік вище порога","Тиша нижче порога","Рівень музики вище порога","Ручний сигнал «Далі»","Біти або тайм-аут"})trigger.Items.Add(label);left.Children.Add(trigger);
  Label(left,"ПОРІГ, dBFS · −60…0",12);left.Children.Add(threshold);Label(left,"КІЛЬКІСТЬ БІТІВ · 1…16",12);left.Children.Add(beatCount);Label(left,"УТРИМАННЯ УМОВИ, мс · 0…30000",12);left.Children.Add(hold);Label(left,"ТАЙМ-АУТ ОЧІКУВАННЯ, мс · 0 = БЕЗ",12);left.Children.Add(timeout);left.Children.Add(new TextBlock{Text="Поріг: бас, пік, рівень або тиша. Утримання вимагає безперервного сигналу після мінімального часу. Тайм-аут переходить далі, навіть якщо умова не настала.",FontSize=10,Foreground=Brushes.Gray,Margin=new(0,12,0,0),TextWrapping=TextWrapping.Wrap});
  var right=new Grid();right.RowDefinitions.Add(new(){Height=GridLength.Auto});right.RowDefinitions.Add(new(){Height=GridLength.Auto});right.RowDefinitions.Add(new(){Height=new(1,GridUnitType.Star)});right.RowDefinitions.Add(new(){Height=GridLength.Auto});Grid.SetColumn(right,2);body.Children.Add(right);
  var fields=new Grid();fields.ColumnDefinitions.Add(new(){Width=new(1,GridUnitType.Star)});fields.ColumnDefinitions.Add(new(){Width=GridLength.Auto});name.Text=effect.Name;fields.Children.Add(name);repeat.IsChecked=effect.Repeat;repeat.VerticalAlignment=VerticalAlignment.Center;repeat.Margin=new(14,0,0,0);Grid.SetColumn(repeat,1);fields.Children.Add(repeat);right.Children.Add(fields);
  var tools=new WrapPanel{Margin=new(0,14,0,14)};Grid.SetRow(tools,1);right.Children.Add(tools);AddButton(tools,"+ Крок",()=>{StopRecording();ApplyFields();if(effect.Steps.Count>=128)throw new ArgumentException("Максимум 128 кроків.");effect.Steps.Insert(selected+1,new EffectStep{Color=palette.Hex});selected++;Refresh();});AddButton(tools,"Дублювати",()=>{StopRecording();ApplyFields();if(effect.Steps.Count>=128)throw new ArgumentException("Максимум 128 кроків.");effect.Steps.Insert(selected+1,effect.Steps[selected].Clone());selected++;Refresh();});record.Margin=new(0,0,8,8);record.Click+=(_,_)=>Safely(ToggleRecording);tools.Children.Add(record);
  var scroll=new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,2);right.Children.Add(scroll);
  var notes=new StackPanel{Margin=new(0,12,0,0)};Grid.SetRow(notes,3);right.Children.Add(notes);notes.Children.Add(info);notes.Children.Add(new TextBlock{Text="Тривалість — мінімальний час кроку. Потім таймер або новий біт перемикає наступний колір. Запис наживо додає кольори після відпускання палітри та запам'ятовує інтервали.",Foreground=new SolidColorBrush(Color.FromRgb(140,140,140)),FontSize=11,TextWrapping=TextWrapping.Wrap,Margin=new(0,8,0,0)});
  var foot=new Grid{Margin=new(0,20,0,0)};Grid.SetRow(foot,2);grid.Children.Add(foot);foot.Children.Add(new TextBlock{Text="Зберігає сценарій кольорів. Під час відтворення потрібні ПК і Bluetooth.",Foreground=new SolidColorBrush(Color.FromRgb(130,130,130)),FontSize=11,VerticalAlignment=VerticalAlignment.Center,MaxWidth=620,HorizontalAlignment=HorizontalAlignment.Left});var save=new Button{Content="Зберегти ефект →",Style=(Style)FindResource("Primary"),HorizontalAlignment=HorizontalAlignment.Right};save.Click+=(_,_)=>Safely(()=>{StopRecording();ApplyFields();effect.Name=name.Text.Trim();effect.Repeat=repeat.IsChecked==true;effect.ValidatePlayable();Result=effect.Clone();DialogResult=true;});foot.Children.Add(save);
  palette.ColorChanged+=color=>{if(!updating&&!recording){effect.Steps[selected].Color=color.Hex;RefreshRowColors();}};palette.ColorCommitted+=color=>{if(recording)RecordColor(color);};duration.TextChanged+=(_,_)=>{if(!updating&&TryDuration(out int ms)){effect.Steps[selected].DurationMs=ms;RefreshRowColors();}};trigger.SelectionChanged+=(_,_)=>{if(!updating&&trigger.SelectedIndex>=0){effect.Steps[selected].Trigger=triggers[trigger.SelectedIndex];if(effect.Steps[selected].Trigger==StepTrigger.MusicBeatOrTimer&&effect.Steps[selected].TimeoutMs==0){effect.Steps[selected].TimeoutMs=3000;timeout.Text="3000";}RefreshRowColors();}};transition.SelectionChanged+=(_,_)=>{if(!updating){effect.Steps[selected].Transition=(StepTransition)Math.Max(0,transition.SelectedIndex);RefreshRowColors();}};foreach(var field in new[]{threshold,beatCount,hold,timeout})field.LostKeyboardFocus+=(_,_)=>{if(!updating)Safely(()=>{ApplyFields();RefreshRowColors();});};Closing+=(_,_)=>StopRecording();Refresh();
 }
 private static void Label(StackPanel panel,string text,double top=0)=>panel.Children.Add(new TextBlock{Text=text,FontSize=9,Foreground=Brushes.Gray,Margin=new(0,top,0,8)});
 private void AddButton(Panel panel,string text,Action action){var button=new Button{Content=text,Padding=new(12,8,12,8),Margin=new(0,0,8,8)};button.Click+=(_,_)=>Safely(action);panel.Children.Add(button);}
 private void Safely(Action action){try{action();}catch(Exception e){info.Text=e.Message;}}
 private bool TryDuration(out int ms){ms=0;if(!double.TryParse(duration.Text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out double seconds)||seconds is <.125 or >60||!double.IsFinite(seconds))return false;ms=(int)Math.Round(seconds*1000);return true;}
 private void ApplyFields(){if(!TryDuration(out int ms))throw new ArgumentException("Тривалість: від 0,125 до 60 секунд.");effect.Steps[selected].DurationMs=ms;effect.Steps[selected].Color=Rgb.Parse(palette.Hex).Hex;var step=effect.Steps[selected];step.ThresholdDb=double.Parse(threshold.Text.Replace(',','.'),CultureInfo.InvariantCulture);step.BeatCount=int.Parse(beatCount.Text,CultureInfo.InvariantCulture);step.HoldMs=int.Parse(hold.Text,CultureInfo.InvariantCulture);step.TimeoutMs=int.Parse(timeout.Text,CultureInfo.InvariantCulture);effect.Validate();}
 private void Refresh()
 {
  selected=Math.Clamp(selected,0,effect.Steps.Count-1);updating=true;var step=effect.Steps[selected];palette.Hex=step.Color;duration.Text=(step.DurationMs/1000.0).ToString("0.###",CultureInfo.InvariantCulture);trigger.SelectedIndex=Array.IndexOf(triggers,step.Trigger);threshold.Text=step.ThresholdDb.ToString("0.##",CultureInfo.InvariantCulture);beatCount.Text=step.BeatCount.ToString();hold.Text=step.HoldMs.ToString();timeout.Text=step.TimeoutMs.ToString();transition.SelectedIndex=(int)step.Transition;updating=false;BuildRows();info.Text=recording?"● Запис: вибирай кольори на палітрі.":$"Крок {selected+1} з {effect.Steps.Count}";
 }
 private void BuildRows(){rows.Children.Clear();for(int i=0;i<effect.Steps.Count;i++){int at=i;var row=new Grid();row.ColumnDefinitions.Add(new(){Width=new(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var select=new Button{Padding=new(12,10,12,10),HorizontalContentAlignment=HorizontalAlignment.Left,Tag=at};select.Click+=(_,_)=>Safely(()=>{StopRecording();ApplyFields();selected=at;Refresh();});row.Children.Add(select);var tools=new StackPanel{Orientation=Orientation.Horizontal,Margin=new(8,0,0,0)};Grid.SetColumn(tools,1);row.Children.Add(tools);foreach(var action in new[]{("↑",-1),("↓",1),("×",0)}){var button=new Button{Content=action.Item1,Padding=new(9,8,9,8),Margin=new(0,0,4,0),IsEnabled=action.Item2==0?effect.Steps.Count>1:at+action.Item2>=0&&at+action.Item2<effect.Steps.Count};button.Click+=(_,_)=>Safely(()=>{StopRecording();ApplyFields();if(action.Item2==0){effect.Steps.RemoveAt(at);selected=Math.Min(selected,effect.Steps.Count-1);}else{int other=at+action.Item2;(effect.Steps[at],effect.Steps[other])=(effect.Steps[other],effect.Steps[at]);selected=other;}Refresh();});tools.Children.Add(button);}rows.Children.Add(new Border{Child=row,Margin=new(0,0,0,9)});}RefreshRowColors();}
 private void RefreshRowColors(){for(int i=0;i<rows.Children.Count;i++){var grid=(Grid)((Border)rows.Children[i]).Child;var button=(Button)grid.Children[0];var s=effect.Steps[i];var color=Rgb.Parse(s.Color);var stack=new StackPanel{Orientation=Orientation.Horizontal};stack.Children.Add(new Border{Width=30,Height=30,CornerRadius=new(9),Background=new SolidColorBrush(Color.FromRgb(color.R,color.G,color.B)),Margin=new(0,0,12,0)});var text=new StackPanel();text.Children.Add(new TextBlock{Text=$"{i+1:D2}   {s.Color}   ·   {s.DurationMs/1000.0:0.###} с",FontSize=12,FontWeight=FontWeights.SemiBold});text.Children.Add(new TextBlock{Text=(s.Transition==StepTransition.Fade?"Плавно":"Миттєво")+" · далі: "+(s.Trigger switch{StepTrigger.MusicBeat or StepTrigger.MusicBeatOrTimer=>$"біти ×{s.BeatCount}",StepTrigger.MusicBass=>$"бас ≥ {s.ThresholdDb} dBFS",StepTrigger.MusicPeak=>$"пік ≥ {s.ThresholdDb} dBFS",StepTrigger.MusicSilence=>$"тиша ≤ {s.ThresholdDb} dBFS",StepTrigger.MusicLevel=>$"рівень ≥ {s.ThresholdDb} dBFS",StepTrigger.Manual=>"ручний сигнал",StepTrigger.MicrophoneSound=>"стара умова — заміни її",_=>"таймер"}),FontSize=10,Foreground=Brushes.Gray,Margin=new(0,4,0,0)});stack.Children.Add(text);button.Content=stack;button.BorderBrush=i==selected?Accent:(Brush)FindResource("Line");}}

 private void ToggleRecording(){if(trigger.SelectedIndex<0)throw new ArgumentException("Вибери таймер або біт музики для цього кроку.");if(recording){StopRecording();Refresh();return;}ApplyFields();live.Start(effect.Steps,Rgb.Parse(palette.Hex),watch.Elapsed.TotalSeconds,triggers[Math.Max(0,trigger.SelectedIndex)],(StepTransition)Math.Max(0,transition.SelectedIndex));CopyCondition(effect.Steps[selected],effect.Steps[^1]);selected=effect.Steps.Count-1;record.Content="■ Завершити запис";Refresh();}
 private void RecordColor(Rgb color){try{live.Record(color,watch.Elapsed.TotalSeconds,triggers[Math.Max(0,trigger.SelectedIndex)],(StepTransition)Math.Max(0,transition.SelectedIndex));CopyCondition(effect.Steps[selected],effect.Steps[^1]);selected=effect.Steps.Count-1;Refresh();}catch(ArgumentException e){StopRecording();info.Text=e.Message;}}
 private static void CopyCondition(EffectStep from,EffectStep to){to.ThresholdDb=from.ThresholdDb;to.BeatCount=from.BeatCount;to.HoldMs=from.HoldMs;to.TimeoutMs=from.TimeoutMs;}
 private void StopRecording(){if(!recording)return;live.Stop(watch.Elapsed.TotalSeconds);record.Content="● Записати наживо";Refresh();}
}
